/**
 * @suppress
 */
public object FfiConverterTypeTransferObserver: FfiConverter<TransferObserver, Long> {
    internal val handleMap = UniffiHandleMap<TransferObserver>()

    override fun lower(value: TransferObserver): Long {
        if (value is TransferObserverImpl) {
             // Rust-implemented object.  Clone the handle and return it
            return value.uniffiCloneHandle()
         } else {
            // Kotlin object, generate a new vtable handle and return that.
            return handleMap.insert(value)
         }
    }

    override fun lift(value: Long): TransferObserver {
        if ((value and 1.toLong()) == 0.toLong()) {
            // Rust-generated handle, construct a new class that uses the handle to implement the
            // interface
            return TransferObserverImpl(UniffiWithHandle, value)
        } else {
            // Kotlin-generated handle, get the object from the handle map
            return handleMap.remove(value)
        }
    }

    override fun read(buf: ByteBuffer): TransferObserver {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: TransferObserver) = 8UL

    override fun write(value: TransferObserver, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}



